package io.tenvyr.platform.domain;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.Json;
import java.util.*;
public final class WorkspaceExecution {
    public static final int PATH_MAX=4096,SOURCE_WORKSPACE_ID_MAX=255,BRANCH_MAX=255,ALLOCATION_INTERRUPT_MS=5*60*1000;
    public static final List<String> MODES=List.of("shared","git-worktree"),STATES=List.of("ALLOCATING","READY","IN_USE","PRESERVED","RELEASE_REQUESTED","TRANSFERRED","REMOVED","FAILED");
    private WorkspaceExecution(){}
    public static ObjectNode parseExecutionWorkspaceIdentity(JsonNode value){if(value==null||value.isNull()||value.isMissingNode())return null;if(!value.isObject())throw invalid("metadata.tenvyr.executionWorkspace must be an object");Set<String> keys=Set.of("schemaVersion","workspaceExecutionId","path","mode","sourceWorkspaceId","baseHeadSha");for(String key:Json.keys(value))if(!keys.contains(key))throw invalid("executionWorkspace contains an unsupported field \""+key+"\"");if(!value.path("schemaVersion").isNumber()||value.path("schemaVersion").asDouble()!=1)throw invalid("executionWorkspace schemaVersion \""+value.path("schemaVersion").asText("undefined")+"\" is not supported");String id=bounded(value.get("workspaceExecutionId"),"workspaceExecutionId",255),path=bounded(value.get("path"),"path",4096),mode=Json.text(value,"mode"),source=bounded(value.get("sourceWorkspaceId"),"sourceWorkspaceId",255);if(!value.path("mode").isTextual()||!MODES.contains(mode))throw invalid("executionWorkspace mode \""+mode+"\" is not supported");String head=Json.text(value,"baseHeadSha");if(value.hasNonNull("baseHeadSha")&&(!value.path("baseHeadSha").isTextual()||!head.matches("[0-9a-f]{40}")))throw invalid("baseHeadSha must be 40 lowercase hex characters or null");return Json.object("schemaVersion",1,"workspaceExecutionId",id,"path",path,"mode",mode,"sourceWorkspaceId",source,"baseHeadSha",head);}
    public static ObjectNode executionWorkspaceFromMetadata(JsonNode metadata){if(metadata==null||metadata.isNull()||metadata.isMissingNode())return null;if(!metadata.isObject())throw invalid("metadata must be an object");JsonNode tenvyr=metadata.get("tenvyr");if(tenvyr==null)return null;if(!tenvyr.isObject())throw invalid("metadata.tenvyr must be an object");return parseExecutionWorkspaceIdentity(tenvyr.get("executionWorkspace"));}
    public static ObjectNode executionWorkspaceIdentityFromRow(JsonNode row){if(!row.hasNonNull("executionPath")||!List.of("READY","IN_USE").contains(Json.text(row,"state","")))return null;return Json.object("schemaVersion",1,"workspaceExecutionId",row.get("id"),"path",row.get("executionPath"),"mode",row.get("mode"),"sourceWorkspaceId",row.get("sourceWorkspaceId"),"baseHeadSha",Json.get(row,"baseHeadSha"));}
    private static String bounded(JsonNode value,String field,int max){if(value==null||!value.isTextual()||value.asText().isEmpty()||value.asText().length()>max)throw invalid(field+" must be a non-empty string of at most "+max+" characters");return value.asText();}
    public static DomainError invalid(String message){return new DomainError("WORKSPACE_EXECUTION_INVALID",message);}
}
